    /// <summary>
    /// Gets or sets the <c>SrsReportRunMailer</c> used for email reports. Set report name
    /// </summary>
    /// <param name = "_mailer">The <c>SrsReportRunMailer</c> object; optional.</param>
    /// <returns>The current <c>SrsReportRunMailer</c> object.</returns>
    public SrsReportRunMailer parmReportRunMailer(SrsReportRunMailer _mailer)
    {
        LanguageId              kpmgLanguageId = CompanyInfo::languageId();
        SysEmailTable           kpmgSysEmailTable;
        SysEmailMessageTable    kpmgSysEmailMessageTable;
        KPMGPrintMgmtSettings   kpmgPrintMgmtSettings;
        PrintMgmtReportFormat   kpmgPrintMgmtReportFormat;
        SrsReportRunMailer      kpmgSrsReportRunMailer = next parmReportRunMailer(_mailer);
        SRSCatalogItemName      kpmgSrsReportName    = reportContract.parmReportName();
        System.DateTime         kpmgCurrentDateTime         = DateTimeUtil::applyTimeZoneOffset(DateTimeUtil::utcNow(), DateTimeUtil::getUserPreferredTimeZone());
        
        select firstonly1 kpmgPrintMgmtSettings
            join kpmgPrintMgmtReportFormat
            where kpmgPrintMgmtReportFormat.Name == kpmgSrsReportName
            && kpmgPrintMgmtReportFormat.RecId == kpmgPrintMgmtSettings.ReportFormat;

        if(kpmgPrintMgmtSettings.KeyVaultCertBlobAccountName && kpmgPrintMgmtSettings.KeyVaultCertBlobAccountKey)
        {
            try
            {
                kpmgSrsReportRunMailer.parmKPMGBlobAccountName(KeyVaultCertificateHelper::getManualSecretValue(kpmgPrintMgmtSettings.KeyVaultCertBlobAccountName));
                kpmgSrsReportRunMailer.parmKPMGBlobAccountKey(KeyVaultCertificateHelper::getManualSecretValue(kpmgPrintMgmtSettings.KeyVaultCertBlobAccountKey));
                kpmgSrsReportRunMailer.parmKPMGBlobContainerName(kpmgPrintMgmtSettings.BlobContainerName);
            }
            catch
            {
                warning("@KPMGAddOn:RetrieveKeyVaultErrorMsg");
            }
        }

        kpmgSrsReportRunMailer.parmKPMGReportName(kpmgSrsReportName);
        
        if(kpmgPrintMgmtSettings.SysEmailId)
        {
            kpmgSrsReportRunMailer.parmKPMGSysEmailId(kpmgPrintMgmtSettings.SysEmailId);
            
            select firstonly SenderAddr
                from kpmgSysEmailTable
                join Subject, Mail
                from kpmgSysEmailMessageTable
                where kpmgSysEmailTable.EmailId == kpmgPrintMgmtSettings.SysEmailId
                    && kpmgSysEmailMessageTable.EmailId == kpmgSysEmailTable.EmailId &&
                      kpmgSysEmailMessageTable.LanguageId == kpmgLanguageId;

            if(kpmgSysEmailTable.SenderAddr)
            {
                kpmgSrsReportRunMailer.parmKPMGFromAddress(kpmgSysEmailTable.SenderAddr);
            }
            
            kpmgSrsReportRunMailer.parmKPMGSysEmailSubject(kpmgSysEmailMessageTable.Subject);
            kpmgSrsReportRunMailer.parmKPMGSysEmailContents(kpmgSysEmailMessageTable.Mail);
        }

        if(kpmgPrintMgmtSettings.Filename)
        {
            kpmgSrsReportRunMailer.parmKPMGFileName(strReplace(kpmgPrintMgmtSettings.Filename, METConstants::PrintMgmtLegalEntityId, curExt()));
            kpmgSrsReportRunMailer.parmKPMGFileName(strReplace(kpmgSrsReportRunMailer.parmKPMGFileName(), METConstants::PrintMgmtTimeStamp, kpmgCurrentDateTime.ToString('yyyyMMddHHmmss')));
            kpmgSrsReportRunMailer.parmKPMGFileName(strReplace(kpmgSrsReportRunMailer.parmKPMGFileName(), METConstants::PrintMgmtDate, kpmgCurrentDateTime.ToString('dd-MM-yyyy')));
        }
        if(kpmgSysEmailMessageTable.Subject)
        {
            kpmgSrsReportRunMailer.parmKPMGSysEmailSubject(strReplace(kpmgSrsReportRunMailer.parmKPMGSysEmailSubject(), METConstants::PrintMgmtDate, kpmgCurrentDateTime.ToString('dd-MM-yyyy')));
        }
        switch  (kpmgSrsReportName)
        {
            case ssrsReportStr(METBankPaymAdviceVendV2, Report):
                this.kpmgUpdateSrsReportRunMailerForRemittance(kpmgSrsReportRunMailer);
                break;
            case ssrsReportStr(METVendInvoiceDocument, Report):
                this.kpmgUpdateSrsReportRunMailerForVendInvoiceDocument(kpmgSrsReportRunMailer);
                break;
            case ssrsReportStr(METCustActivityStatement, Report):
            case ssrsReportStr(METCustActivityStatement, ReportMulti): // MPJ-15231
                this.kpmgUpdateSrsReportRunMailerForMETCustActivityStatement(kpmgSrsReportRunMailer);
                break;
            case ssrsReportStr(KPMGCustAccountStatementExt, Report):
            case ssrsReportStr(KPMGCustAccountStatementExt, ReportTasLiq):
            case ssrsReportStr(KPMGCustAccountStatementExt, ReportMultiCust): // MPJ-15231
                this.kpmgUpdateSrsReportRunMailerForCustStatementExt(kpmgSrsReportRunMailer);
                break;
            case ssrsReportStr(KPMGFreeTextInvoice, Report):
                this.kpmgUpdateSrsReportRunMailerForFreeTextInvoice(kpmgSrsReportRunMailer);
                break;
            case ssrsReportStr(KPMGPurchPurchaseOrder, Report):
                this.kpmgUpdateSrsReportRunMailerForPurchaseOrder(kpmgSrsReportRunMailer);
                break;
            case ssrsReportStr(CustCollectionJour, Report):
                this.kpmgUpdateSrsReportRunMailerForCustCollection(kpmgSrsReportRunMailer);
                break;
            case ssrsReportStr(METCustInterestNote, Report):
                this.kpmgUpdateSrsReportRunMailerForMETCustInterestNote(kpmgSrsReportRunMailer);
                break;
            case ssrsReportStr(METPurchPurchaseOrder, ReportImport):
            case ssrsReportStr(METPurchPurchaseOrder, ReportTrade):
                this.metUpdateSrsReportRunMailerForPurchaseOrder(kpmgSrsReportRunMailer);
                break;
            /*CB714_POConfirmationReports -start
            case ssrsReportStr(KPMGPurchPurchaseOrder, Food):
            case ssrsReportStr(KPMGPurchPurchaseOrder, Liquor):
            case ssrsReportStr(KPMGPurchPurchaseOrder, Hardware):
            case ssrsReportStr(KPMGPurchPurchaseOrder, Report_IMP):
                this.kpmgUpdateSrsReportRunMailerForPurchaseOrderFoodLiqHwe(kpmgSrsReportRunMailer);
                break;
            CB714_POConfirmationReports -end*/

            /* CB730_PrintManagementPlaceHoder - once report is developed we can remove comment for particular report
            case ssrsReportStr(METSOLoadPlanningAid, Report):
                this.metUpdateSrsReportRunMailerForSOLoadPlanningAid(kpmgSrsReportRunMailer);
                break;
            
            case ssrsReportStr(METSOLoadPlanningReport, Report):
                this.metUpdateSrsReportRunMailerForSOLoadPlanningReport(kpmgSrsReportRunMailer);
                break;
            
            case ssrsReportStr(METTOLoadPlanningAid, Report):
                this.metUpdateSrsReportRunMailerForTOLoadPlanningAid(kpmgSrsReportRunMailer);
                break;
            
            case ssrsReportStr(METTOLoadPlanningReport, Report):
                this.metUpdateSrsReportRunMailerForTOLoadPlanningReport(kpmgSrsReportRunMailer);
                break;
            
            case ssrsReportStr(METSOCoverNotes, Report):
                this.metUpdateSrsReportRunMailerForSOCoverNotes(kpmgSrsReportRunMailer);
                break;
            
            case ssrsReportStr(METSODangerousManifest, Report):
                this.metUpdateSrsReportRunMailerForSODangerousManifest(kpmgSrsReportRunMailer);
                break;
            
            case ssrsReportStr(METSOContinuingPermissionNote, Report):
                this.metUpdateSrsReportRunMailerForSOContinuingPermissionNote(kpmgSrsReportRunMailer);
                break;
            
            case ssrsReportStr(METPickupAdvice, Report):
                this.metUpdateSrsReportRunMailerForPickupAdvice(kpmgSrsReportRunMailer);
                break;
            
            case ssrsReportStr(METSOMultimodalDangerousGoods, Report):
                this.metUpdateSrsReportRunMailerForSOMultimodalDangerousGoods(kpmgSrsReportRunMailer);
                break;
            */
            case ssrsReportStr(METCCRReport, Report):
                this.metUpdateSrsReportRunMailerForContainerContentReport(kpmgSrsReportRunMailer);
                break;
            

            //CB730_PrintManagementPlaceHoder - Code added for placeholder of file name for SO incoice and Delivery note report
            case ssrsReportStr(KPMGSalesPackingSlip, DeliveryNote):
            case ssrsReportStr(SalesPackingSlip, Report):
                this.metUpdateSrsReportRunMailerForSODeliveryNote(kpmgSrsReportRunMailer);
                break;
            
            case ssrsReportStr(SalesInvoice, Report):
            case ssrsReportStr(KPMGSalesInvoice, Report):
                this.metUpdateSrsReportRunMailerForSOInvoice(kpmgSrsReportRunMailer);
                break;

            /* CB730_PrintManagementPlaceHoder - Commented becasuse the reports are yet to be developed
            case ssrsReportStr(METTOShipment, Report):
                this.metUpdateSrsReportRunMailerForTOShipment(kpmgSrsReportRunMailer);
                break;

            case ssrsReportStr(METTOCoverNotes, Report):
                this.metUpdateSrsReportRunMailerForTOCoverNotes(kpmgSrsReportRunMailer);
                break;
            
            case ssrsReportStr(METTODangerousManifest, Report):
                this.metUpdateSrsReportRunMailerForTODangerousManifest(kpmgSrsReportRunMailer);
                break;
            
            case ssrsReportStr(METTOContinuingPermissionNote, Report):
                this.metUpdateSrsReportRunMailerForTOContinuingPermissionNote(kpmgSrsReportRunMailer);
                break;
            
            case ssrsReportStr(METTOMultimodalDangerousGoods, Report):
                this.metUpdateSrsReportRunMailerForTOMultimodalDangerousGoods(kpmgSrsReportRunMailer);
                break;
                Commented
                */

            default:
                break;
        }

        return kpmgSrsReportRunMailer;
    }

    /// <summary>
    /// Update Filename and subject in SrsReportRunMailer object
    /// </summary>
    /// <param name = "_kpmgSRSReportRunMailer">Type SrsReportRunMailer</param>
    private void kpmgUpdateSrsReportRunMailerForRemittance(SrsReportRunMailer    _kpmgSRSReportRunMailer)
    {
        METBankPaymAdviceContract   kpmgBankPaymAdviceContract = reportContract.parmRdpContract() as METBankPaymAdviceContract;
        Filename                    kpmgFileName                = _kpmgSRSReportRunMailer.parmKPMGFileName();
        SysEmailSubject             kpmgEmailSubject            = _kpmgSRSReportRunMailer.parmKPMGSysEmailSubject();

        if(kpmgFileName)
        {
            kpmgFileName    = strReplace(kpmgFileName, METConstants::PrintMgmtAccountNum, kpmgBankPaymAdviceContract.parmAccountNum());
            kpmgFileName    = strReplace(kpmgFileName, METConstants::PrintMgmtPaymentReference, kpmgBankPaymAdviceContract.parmLedgerJournalId());
        
            _kpmgSRSReportRunMailer.parmKPMGFileName(kpmgFileName);
        }
        if(kpmgEmailSubject)
        {
            kpmgEmailSubject    = strReplace(kpmgEmailSubject, METConstants::PrintMgmtAccountNum, kpmgBankPaymAdviceContract.parmAccountNum());
            kpmgEmailSubject    = strReplace(kpmgEmailSubject, METConstants::PrintMgmtVendorName, VendTable::find(kpmgBankPaymAdviceContract.parmAccountNum()).name());
            _kpmgSRSReportRunMailer.parmKPMGSysEmailSubject(kpmgEmailSubject);
        }
    }

/// <summary>
/// Update Filename and subject in SrsReportRunMailer object
/// </summary>
/// <param name = "_kpmgSRSReportRunMailer">Type SrsReportRunMailer</param>
private void kpmgUpdateSrsReportRunMailerForVendInvoiceDocument(SrsReportRunMailer    _kpmgSRSReportRunMailer)
{
    VendInvoiceDocumentContract kpmgVendInvoiceDocmentContract = reportContract.parmRdpContract() as VendInvoiceDocumentContract;
    Filename                    kpmgFileName                = _kpmgSRSReportRunMailer.parmKPMGFileName();
    SysEmailSubject             kpmgEmailSubject            = _kpmgSRSReportRunMailer.parmKPMGSysEmailSubject();
    VendInvoiceJour             kpmgVendInvoiceJour         = VendInvoiceJour::findRecId(kpmgVendInvoiceDocmentContract.parmRecordId());
    if(kpmgFileName)
    {
        kpmgFileName    = strReplace(kpmgFileName, METConstants::PrintMgmtAccountNum, kpmgVendInvoiceJour.InvoiceAccount);
        kpmgFileName    = strReplace(kpmgFileName, METConstants::PrintMgmtInvoiceNum, kpmgVendInvoiceJour.InvoiceId);
        _kpmgSRSReportRunMailer.parmKPMGFileName(kpmgFileName);
    }
    if(kpmgEmailSubject)
    {
        kpmgEmailSubject    = strReplace(kpmgEmailSubject, METConstants::PrintMgmtAccountNum, kpmgVendInvoiceJour.InvoiceAccount);
        kpmgEmailSubject    = strReplace(kpmgEmailSubject, METConstants::PrintMgmtVendorName, kpmgVendInvoiceJour.vendName());
        _kpmgSRSReportRunMailer.parmKPMGSysEmailSubject(kpmgEmailSubject);
    }
}

    /// <summary>
    /// Update Filename and subject in SrsReportRunMailer object
    /// </summary>
    /// <param name = "_kpmgSRSReportRunMailer">Type SrsReportRunMailer</param>
    private void kpmgUpdateSrsReportRunMailerForMETCustActivityStatement(SrsReportRunMailer    _kpmgSRSReportRunMailer)
    {
        METCustActivityStatementContract    metCustActivityStatementContract = reportContract.parmRdpContract() as METCustActivityStatementContract;
        Filename                            kpmgFileName                = _kpmgSRSReportRunMailer.parmKPMGFileName();
        SysEmailSubject                     kpmgEmailSubject            = _kpmgSRSReportRunMailer.parmKPMGSysEmailSubject();
        CustAccount                         kpmgCustAccount             = metCustActivityStatementContract.parmCSAccountNum();
        CustTable                           kpmgCustTable               = CustTable::find(kpmgCustAccount);

        if(kpmgFileName)
        {
            kpmgFileName        = strReplace(kpmgFileName, METConstants::PrintMgmtAccountNum, kpmgCustTable.AccountNum);
            if(strContains(kpmgFileName, METConstants::PrintMgmtPillar))
            {
                kpmgFileName        = strReplace(kpmgFileName, METConstants::PrintMgmtPillar, METHelper::getDimensionValue(kpmgCustTable.DefaultDimension, METConstants::pillar));
            }
            if(strContains(kpmgFileName, METConstants::PrintMgmtState))
            {
                kpmgFileName        = strReplace(kpmgFileName, METConstants::PrintMgmtState, METHelper::getDimensionValue(kpmgCustTable.DefaultDimension, METConstants::state));
            }
            if(strContains(kpmgFileName, METConstants::PrintMgmtIndustryKey))
            {
                kpmgFileName        = strReplace(kpmgFileName, METConstants::PrintMgmtIndustryKey, METCustTable::find(kpmgCustAccount).IndustryKey);
            }
            _kpmgSRSReportRunMailer.parmKPMGFileName(kpmgFileName);
        }
        if(kpmgEmailSubject)
        {
            kpmgEmailSubject    = strReplace(kpmgEmailSubject, METConstants::PrintMgmtAccountNum, kpmgCustAccount);
            kpmgEmailSubject    = strReplace(kpmgEmailSubject, METConstants::PrintMgmtCustomerName, kpmgCustTable.name());
            _kpmgSRSReportRunMailer.parmKPMGSysEmailSubject(kpmgEmailSubject);
        }
    }

