    /// <summary>
    /// Update Filename and subject in SrsReportRunMailer object
    /// </summary>
    /// <param name = "_kpmgSRSReportRunMailer">Type SrsReportRunMailer</param>
    private void kpmgUpdateSrsReportRunMailerForPurchaseOrder(SrsReportRunMailer    _kpmgSRSReportRunMailer)
    {

        PurchPurchaseOrderContract          kpmgPurchPurchaseOrderContract  = reportContract.parmRdpContract() as PurchPurchaseOrderContract;
        PurchTable                          kpmgPurchTable                  = PurchTable::findRecId(kpmgPurchPurchaseOrderContract.parmRecordId());
        VendAccount                         kpmgVendAccount                 = kpmgPurchTable.InvoiceAccount;
        Filename                            kpmgFileName                    = _kpmgSRSReportRunMailer.parmKPMGFileName();
        SysEmailSubject                     kpmgEmailSubject                = _kpmgSRSReportRunMailer.parmKPMGSysEmailSubject();
        
        if(kpmgFileName)
        {
            kpmgFileName        = strReplace(kpmgFileName, METConstants::PrintMgmtAccountNum, kpmgVendAccount);
            kpmgFileName        = strReplace(kpmgFileName, METConstants::PrintMgmtPurchId, kpmgPurchTable.PurchId);
            _kpmgSRSReportRunMailer.parmKPMGFileName(kpmgFileName);
        }
        if(kpmgEmailSubject)
        {
            kpmgEmailSubject    = strReplace(kpmgEmailSubject, METConstants::PrintMgmtAccountNum, kpmgVendAccount);
            kpmgEmailSubject    = strReplace(kpmgEmailSubject, METConstants::PrintMgmtVendorName, kpmgPurchTable.invoiceName());
            _kpmgSRSReportRunMailer.parmKPMGSysEmailSubject(kpmgEmailSubject);
        }
    }

    /// <summary>
    /// Update Filename and subject in SrsReportRunMailer object
    /// </summary>
    /// <param name = "_kpmgSRSReportRunMailer">Type SrsReportRunMailer</param>
    private void kpmgUpdateSrsReportRunMailerForPurchaseOrderFoodLiqHwe(SrsReportRunMailer    _kpmgSRSReportRunMailer)
    {
        PurchTable                          kpmgPurchTable;
        //METPlannerCodeSetup                 METPlannerCodeSetup;
        Map                                 metPOEmailSubjectMap, metPOEmailContentMap;
        METPurchTable                       METPurchTable;
        VendPurchOrderJour                  kpmgVendPurchOrderJourStd;
        str                                 kpmgVersionNum, kpmgPOStatus, kpmgDocNum;
        Filename                            kpmgFileName        = _kpmgSRSReportRunMailer.parmKPMGFileName();
        SysEmailSubject                     kpmgEmailSubject    = _kpmgSRSReportRunMailer.parmKPMGSysEmailSubject();
        SysEmailContents                    kpmgEmailContents   = _kpmgSRSReportRunMailer.parmKPMGSysEmailContents();
        SrsReportDataContract               kpmgContract        = reportContract;

        if(kpmgContract && kpmgContract.parmRdpContract() as PurchPurchaseOrderContract)
        {
            PurchPurchaseOrderContract kpmgPurchConfirmContract  = kpmgContract.parmRdpContract() as PurchPurchaseOrderContract;
            
            kpmgVendPurchOrderJourStd   = VendPurchOrderJour::findRecId(kpmgPurchConfirmContract.parmRecordId());
            kpmgPurchTable              = kpmgVendPurchOrderJourStd.purchTable();
            
            kpmgDocNum      = kpmgVendPurchOrderJourStd.PurchOrderDocNum;
            kpmgVersionNum  = subStr(kpmgDocNum, strFind(kpmgDocNum, metConstants::hyphen, 1, strLen(kpmgDocNum))+1, strLen(kpmgDocNum));

            metPOEmailSubjectMap = new Map(Types::String, Types::String);
            metPOEmailSubjectMap.insert(METConstants::PONumber, kpmgVendPurchOrderJourStd.PurchId);
            metPOEmailSubjectMap.insert(METConstants::POVersionNumber, kpmgVersionNum);
            if(kpmgFileName)
            {
                _kpmgSRSReportRunMailer.parmKPMGFileName(SysEmailMessage::stringExpand(kpmgFileName, metPOEmailSubjectMap));
            }

            if(kpmgPurchTable.PurchStatus == PurchStatus::Canceled)
            {
                kpmgPOStatus = metConstants::Cancelled;
            }
            else if(str2Num(kpmgVersionNum) == 1)
            {
                kpmgPOStatus = metConstants::Created;
            }
            else
            {
                kpmgPOStatus = metConstants::Amended;
            }
            metPOEmailSubjectMap.insert(METConstants::POStatus, kpmgPOStatus);
            metPOEmailSubjectMap.insert(METConstants::WarehouseName, InventLocation::find(kpmgPurchTable.InventLocationId).Name);
            if(kpmgEmailSubject)
            {
                _kpmgSRSReportRunMailer.parmKPMGSysEmailSubject(SysEmailMessage::stringExpand(kpmgEmailSubject, metPOEmailSubjectMap));
            }

            metPOEmailContentMap = new Map(Types::String, Types::String);
            metPOEmailContentMap.insert(METConstants::PONumber, kpmgVendPurchOrderJourStd.PurchId);
            metPOEmailContentMap.insert(METConstants::POStatus, kpmgPOStatus);
            metPOEmailContentMap.insert(METConstants::POCurrency, kpmgPurchTable.CurrencyCode);
            metPOEmailContentMap.insert(METConstants::POAmount, strFmt("@SYS82282",kpmgVendPurchOrderJourStd.Amount));

            // Task 90134: CB220 - Planner Codes - Check/Update Build
            // TODO Commenting for now, will have to be updated with buyer group logic
            /*
            select firstonly PlannerCodePersonnelNumber from METPlannerCodeSetup
                    exists join METPurchTable
                    where METPurchTable.POPlannerCode == METPlannerCodeSetup.PlannerCode
                    && METPurchTable.PurchId == kpmgPurchTable.PurchId;
            if(METPlannerCodeSetup.PlannerCodePersonnelNumber)
            {
                metPOEmailContentMap.insert(METConstants::PlannerName, HcmWorker::worker2Name(METPlannerCodeSetup.PlannerCodePersonnelNumber));
            }*/

            if(kpmgEmailContents)
            {
                _kpmgSRSReportRunMailer.parmKPMGSysEmailContents(SysEmailMessage::stringExpand(kpmgEmailContents, SysEmailTable::htmlEncodeParameters(metPOEmailContentMap)));
            }
        }
    }

    /// <summary>
    /// CB713 PO Confirmation output report 
    /// updpate the print management report parameters
    /// </summary>
    /// <param name = "_metSRSReportRunMailer">_metSRSReportRunMailer</param>
    private void metUpdateSrsReportRunMailerForPurchaseOrder(SrsReportRunMailer _metSRSReportRunMailer)
    {
        SrsReportDataContract               metContract        = reportContract;
        
        if (metContract && metContract.parmRdpContract() as PurchPurchaseOrderContract)
        {
            Map                         metPOEmailSubjectMap, metPOEmailContentMap;
            str                         metVersionNum, metPOStatus, metDocNum;
            Filename                    metFileName = _metSRSReportRunMailer.parmKPMGFileName();
            SysEmailSubject             metEmailSubject = _metSRSReportRunMailer.parmKPMGSysEmailSubject();
            SysEmailContents            metEmailContents = _metSRSReportRunMailer.parmKPMGSysEmailContents();
            PurchPurchaseOrderContract  metPurchConfirmContract = metContract.parmRdpContract() as PurchPurchaseOrderContract;
            SRSPrintDestinationSettings metPrintDestinationSettings = metContract.parmPrintSettings();

            metFileName = metPrintDestinationSettings.parmFileName();
            metEmailSubject = metPrintDestinationSettings.emailSubject();
            metEmailContents = metPrintDestinationSettings.emailbody();

            VendPurchOrderJour metVendPurchOrderJourStd = VendPurchOrderJour::findRecId(metPurchConfirmContract.parmRecordId());
            PurchTable purchTable = metVendPurchOrderJourStd.purchTable();
            
            metDocNum = metVendPurchOrderJourStd.PurchOrderDocNum;
            metVersionNum = subStr(metDocNum, strFind(metDocNum, metConstants::hyphen, 1, strLen(metDocNum))+1, strLen(metDocNum));

            metPOEmailSubjectMap = new Map(Types::String, Types::String);
            metPOEmailSubjectMap.insert(METConstants::PONumber, metVendPurchOrderJourStd.PurchId);
            metPOEmailSubjectMap.insert(METConstants::POVersionNumber, metVersionNum);
            
            if (metFileName)
            {
                _metSRSReportRunMailer.parmkpmgFileName(SysEmailMessage::stringExpand(metFileName, metPOEmailSubjectMap));
            }

            if (purchTable.PurchStatus == PurchStatus::Canceled)
            {
                metPOStatus = metConstants::Cancelled;
            }
            else if (str2Num(metVersionNum) == 1)
            {
                metPOStatus = metConstants::Created;
            }
            else
            {
                metPOStatus = metConstants::Amended;
            }

            metPOEmailSubjectMap.insert(METConstants::POStatus, metPOStatus);
            metPOEmailSubjectMap.insert(METConstants::WarehouseName, InventLocation::find(purchTable.InventLocationId).Name);
            if (metEmailSubject)
            {
                _metSRSReportRunMailer.parmkpmgSysEmailSubject(SysEmailMessage::stringExpand(metEmailSubject, metPOEmailSubjectMap));
            }

            metPOEmailContentMap = new Map(Types::String, Types::String);
            metPOEmailContentMap.insert(METConstants::PONumber, metVendPurchOrderJourStd.PurchId);
            metPOEmailContentMap.insert(METConstants::POStatus, metPOStatus);
            metPOEmailContentMap.insert(METConstants::POCurrency, purchTable.CurrencyCode);
            metPOEmailContentMap.insert(METConstants::POAmount, strFmt("@SYS82282", metVendPurchOrderJourStd.Amount));
            metPOEmailContentMap.insert(METConstants::POVersionNumber, metVersionNum);
            metPOEmailContentMap.insert(METConstants::WarehouseName, InventLocation::find(purchTable.InventLocationId).Name);
            metPOEmailContentMap.insert(METConstants::BuyerName, HcmWorker::find(InventBuyerGroup::find(purchTable.ItemBuyerGroupId).METOrderer).name());

            if (metEmailContents)
            {
                _metSRSReportRunMailer.parmkpmgSysEmailContents(SysEmailMessage::stringExpand(metEmailContents, SysEmailTable::htmlEncodeParameters(metPOEmailContentMap)));
            }
        }
    }

