    /// updpate the print management report parameters
    /// </summary>
    /// <param name = "_metSRSReportRunMailer">_metSRSReportRunMailer</param>
    private void metUpdateSrsReportRunMailerForContainerContentReport(SrsReportRunMailer _kpmgSRSReportRunMailer)
    {
        SrsReportDataContract               metContract        = reportContract;

        if(metContract && metContract.parmRdpContract() as METCommonPrintDestinationContract)
        {
            METCommonPrintDestinationContract   metCommonPrintDestinationContract   = metContract.parmRdpContract() as METCommonPrintDestinationContract;
            SRSPrintDestinationSettings         metPrintDestinationSettings         = metContract.parmPrintSettings();

            METSalesOrderShipmentLoadHeader     metSOShipmentLoadHeader;

            select firstonly metSOShipmentLoadHeader
                where metSOShipmentLoadHeader.RecId == metCommonPrintDestinationContract.parmRecordId();
            
            str                                 metValue        = metSOShipmentLoadHeader.CustAccount;// to be assigned to set the dynamic value
            Filename                            metFileName     = metPrintDestinationSettings.parmFileName();

            if(metFileName)
            {
                metFileName        = strReplace(metFileName, METConstants::PrintMgmtCustomerId, metValue);
            
                _kpmgSRSReportRunMailer.parmKPMGFileName(metFileName);
            }
        }
        
    }

